language "kql/2";
module ken.catalog.iterator;
import ken.catalog.iterator.variants.async_iterator;
import ken.catalog.iterator.variants.callback_iterator;
import ken.catalog.iterator.variants.delegated_cursor;
import ken.catalog.iterator.variants.delegated_generator;
import ken.catalog.iterator.variants.explicit_cursor;
import ken.catalog.iterator.variants.external_cursor;
import ken.catalog.iterator.variants.generator;
import ken.catalog.iterator.variants.paired_cursor;

pattern detect(out GraphTerm $iterator) {
  either {
    use ken.catalog.iterator.variants.external_cursor.detect(iterator: $iterator);
  } or {
    either {
      use ken.catalog.iterator.variants.generator.detect(iterator: $iterator);
    } or {
      use ken.catalog.iterator.variants.delegated_generator.detect(iterator: $iterator);
    } or {
      use ken.catalog.iterator.variants.explicit_cursor.detect(iterator: $iterator);
    } or {
      use ken.catalog.iterator.variants.paired_cursor.detect(iterator: $iterator);
    } or {
      use ken.catalog.iterator.variants.delegated_cursor.detect(iterator: $iterator);
    } or {
      use ken.catalog.iterator.variants.async_iterator.detect(iterator: $iterator);
    } or {
      use ken.catalog.iterator.variants.callback_iterator.detect(iterator: $iterator);
    }
  }
}

query results {
  use detect(iterator: $iterator);
  select $iterator;
}

variants.query:
language "kql/2";
module ken.catalog.iterator.variants.external_cursor;

pattern detect(out TypeDecl $iterator) {
  type $iterator {
    language: "cpp";
    field $position { }
    method $advance { name: "next"; constructor: false; }
    method $test { name: "isDone"; constructor: false; }
    method $current { name: "currentItem"; constructor: false; }
  }
  where reads($advance, $position);
  where writes($advance, $position);
  where reads($test, $position);
  where reads($current, $position);
}

query results {
  use detect(iterator: $iterator);
  select $iterator;
}

language "kql/2";
module ken.catalog.iterator.variants.generator;

pattern detect(out Callable $iterator) {
  callable $iterator {
    generator: true;
    context_manager: false;
    body { yield _; }
  }
}

query results {
  use detect(iterator: $iterator);
  select $iterator;
}

language "kql/2";
module ken.catalog.iterator.variants.delegated_generator;

pattern detect(out Callable $iterator) {
  callable $iterator {
    generator: true;
    context_manager: false;
    body { yield from _; }
  }
}

query results {
  use detect(iterator: $iterator);
  select $iterator;
}

language "kql/2";
module ken.catalog.iterator.variants.explicit_cursor;

pattern detect(out TypeDecl $iterator) {
  type $iterator {
    language: "python";
    field $state { }
    method $iter { name: "__iter__"; constructor: false; }
    method $next { name: "__next__"; constructor: false; }
  }
  where returns_self($iter, $iterator);
  where writes($next, $state);
  where reads($next, $state);
}

query results {
  use detect(iterator: $iterator);
  select $iterator;
}

language "kql/2";
module ken.catalog.iterator.variants.callback_iterator;

pattern detect(out GraphTerm $iterator, out Parameter $callback, out Call $call, out Operation $loop, out Binding $element, out Operation $branch, out Operation $exit) {
  operation $branch { kind: "branch"; }
  either {
    callable $iterator {
      param $callback {}
      body {
        iterate $collection as $element as $loop {
          body {
            let $accepted = call $callback { argument $element at any; } as $call;
            if ($accepted == false) { return as $exit; }
          }
        }
      }
    }
  } or {
    callable $iterator {
      param $callback {}
      body {
        iterate $collection as $element as $loop {
          body {
            let $accepted = call $callback { argument $element at any; } as $call;
            if ($accepted == false) { break $loop as $exit; }
          }
        }
      }
    }
  } or {
    callable $iterator {
      param $callback {}
      body {
        iterate $collection as $element as $loop {
          body {
            let $accepted = call $callback { argument $element at any; } as $call;
            if ($accepted) { } else { return as $exit; }
          }
        }
      }
    }
  } or {
    callable $iterator {
      param $callback {}
      body {
        iterate $collection as $element as $loop {
          body {
            let $accepted = call $callback { argument $element at any; } as $call;
            if ($accepted) { } else { break $loop as $exit; }
          }
        }
      }
    }
  }
}

query results {
  use detect(iterator: $iterator, callback: $callback, call: $call, loop: $loop, element: $element, branch: $branch, exit: $exit);
  select $iterator, $callback, $call, $loop, $element, $branch, $exit;
}

language "kql/2";
module ken.catalog.iterator.variants.async_iterator;

pattern detect(out Callable $iterator, out Callable $producer, out Operation $loop, out Call $source, out Operation $suspend) {
  callable $producer {
    async: true;
    body { yield _ as $suspend; }
  }
  callable $iterator {
    async: true;
    call $source { target: $producer; }
    body {
      iterate $source as $item as $loop {
        async: true;
        body {}
      }
    }
  }
  where $iterator != $producer;
}

query results {
  use detect(iterator: $iterator, producer: $producer, loop: $loop, source: $source, suspend: $suspend);
  select $iterator, $producer, $loop, $source, $suspend;
}

language "kql/2";
module ken.catalog.iterator.variants.paired_cursor;

pattern detect(out TypeDecl $iterator) {
  type $iterator {
    field $state { }
    method $next { name: "next"; constructor: false; }
    method $test { name: "hasNext"; constructor: false; }
  }
  where writes($next, $state);
  where reads($next, $state);
  where reads($test, $state);
}

query results {
  use detect(iterator: $iterator);
  select $iterator;
}

language "kql/2";
module ken.catalog.iterator.variants.delegated_cursor;

pattern detect(out TypeDecl $iterator, out Call $local_advance) {
  type $iterator {
    field $cursor { }
    method $iter { name: "__iter__"; constructor: false; }
    method $next {
      name: "__next__"; constructor: false;
      body {
        let $local_result = call $advance { argument $cursor at any; } as $local_advance;
        return $local_result;
      }
    }
  }
  where returns_self($iter, $iterator);
  where advances($local_advance, $cursor);
}

query results {
  use detect(iterator: $iterator);
  select $iterator;
}

