language "kql/2";
module ken.catalog.iterator.iterate_over;

pattern detect(out GraphTerm $source, out Binding $item, out Operation $body, out Operation $iteration) {
  callable $unit {
    body {
      iterate $source as $item as $iteration { body: $body; body {} }
    }
  }
}

query results {
  use detect(source: $source, item: $item, body: $body, iteration: $iteration);
  select $source, $item, $body, $iteration;
}

language "kql/2";
module ken.catalog.iterator.advancing_element;
import ken.catalog.iterator;

pattern detect(out TypeDecl $unit) {
  use ken.catalog.iterator.detect(iterator: $unit);
  type $unit {
    field $index {}
    field $items {}
    method $next {
      name: ["next", "__next__"]; constructor: false;
      body {
        let $value = $items[$index];
        $index = $index + 1;
        return $value;
      }
    }
  }
}

query results {
  use detect(unit: $unit);
  select $unit;
}

